```php
final class OffPeakPricing
{
    /** Returns the multiplier if the event falls within the window, otherwise null. */
    public static function multiplierAt(?string $windowStart, ?string $windowEnd, ?string $multiplier, \DateTimeImmutable $utc): ?string
    {
        if ($windowStart === null || $windowEnd === null || $multiplier === null) return null;
        $minutes = (int)$utc->format('G') * 60 + (int)$utc->format('i');
        $window = new OffPeakWindow(TimeOfDay::parseHhMm($windowStart), TimeOfDay::parseHhMm($windowEnd));
        return $window->contains($minutes) ? $multiplier : null;
    }
}
