```php
final class SpecReader
{
    public function __construct(private string $context) {}

    public static function requiredString(array $item, string $key, string $context, int $maxLen = 255): string
    {
        $value = $item[$key] ?? null;
        if (!is_string($value) || $value === '' || mb_strlen($value) > $maxLen) {
            throw new BadInputException("{$context}.{$key}: expected a non-empty string (no more than {$maxLen} characters)");
        }
        return $value;
    }

    public static function optionalString(array $item, string $key, string $context, int $maxLen = 255): ?string
    {
        if (!array_key_exists($key, $item)) return null;
        $value = $item[$key];
        if ($value === null) return null;
        if (!is_string($value) || $value === '' || mb_strlen($value) > $maxLen) {
            throw new BadInputException(...);
        }
        return $value;
    }

    public static function integer(array $item, string $key, string $context): int
    {
        $value = $item[$key] ?? null;
        if (!is_int($value) || $value < 0) {
            throw new BadInputException("{$context}.{$key}: expected a non-negative integer");
