public static function rates(array $item, PriceUnit $unit, string $context): array
{
    $rates = $item['rates'] ?? null;
    if (!is_array($rates) || array_is_list($rates)) throw new BadInputException("{$context}.rates: expected an object of kind → price");
    $required = $unit === PriceUnit::Per1mTokensUnified ? ['any'] : ['input','output','cache_read','cache_write'];
    $result = [];
    foreach ($required as $kind) {
        $value = $rates[$kind] ?? null;
        if (!is_string($value)) throw new BadInputException("{$context}.rates.{$kind}: expected a decimal string (not a JSON number)");
        DecimalLiteral::assertNonNegative($value, "{$context}.rates.{$kind}");
        $result[$kind] = $value;
    }
    return $result;
}
