    /** @throws ... (shouldn't happen) */
    public function rate(): RatingSummary
    {
        return $this->em->transactional(function () {
            $events = $this->em->createQuery(
                'SELECT e FROM ' . UsageEvent::class . ' e WHERE e.status IN (:new, :unrated) ORDER BY e.id ASC'
            )->getQuery()->setParameter('new', UsageEvent::STATUS_NEW)->setParameter('unrated', UsageEvent::STATUS_UNRATED)->getResult();

            $rated = 0;
            $unratedList = [];
            $now = new \DateTimeImmutable('now', new \DateTimeZone('UTC'));

            foreach ($events as $event) {
                $priceRow = $this->findEffectivePriceRow($event->getModel(), $event->getTs());
                if ($priceRow === null) {
                    $event->markUnrated();
                    $unratedList[] = $event;
                    continue;
                }

                $multiplier = $this->offPeakMultiplierFor($event);
                $cost = $this->calculator->calculateEventCost($priceRow->unit(), $event->tokens(), $priceRow->getRates(), $multiplier);
                $event->markRated($priceRow, $cost, $now);
                $rated++;
            }

            $this->em->flush();
            return new RatingSummary($rated, $unratedList);
        });
    }

    private function findEffectivePriceRow(Model $model, \DateTimeImmutable $ts): ?PriceRow
    {
        /** @var PriceRow|null $row */
        $row = $this->em->createQuery(
            'SELECT p FROM ' . PriceRow::class . ' p WHERE p.model = :model AND p.validFrom <= :ts ORDER BY p.validFrom DESC'
        )->getQuery()->setParameter('model', $model)->setParameter('ts', $ts)->setMaxResults(1)->getOneOrNullResult();

        return $row;
    }

    private function offPeakMultiplierFor(UsageEvent $event): ?string
    {
        $provider = $event->getProvider();
        $pid = $provider->getId();
        if (!array_key_exists($pid, $this->offPeakByProvider)) {
            $this->offPeakByProvider[$pid] = OffPeakPricing::multiplierAt(
                $provider->getOffPeakWindowStart(),
                $provider->getOffPeakWindowEnd(),
                $provider->getOffPeakMultiplier(),
                $event->getTs(),
            );
        }
        return $this->offPeakByProvider[$pid];
    }
}
