```php
<?php

declare(strict_types=1);

namespace App\Billing\Pricing;

use App\Shared\Math\Decimal;
use InvalidArgumentException;

final class PricingCalculator
{
    public const KINDS = ['input', 'output', 'cache_read', 'cache_write'];

    /**
     * Final cost of the event in USD.
     *
     * All intermediate values are inexact decimals (extra precision),
     * and only the final result is rounded: 6 decimal places, HALF_UP.
     *
     * @param array{input: int, output: int, cache_read: int, cache_write: int} $tokens
     * @param array<string, string> $rates price by kind (decimals as strings)
     * @param string|null $offPeakMultiplier null — no off-peak discount
     */
    public function calculateEventCost(PriceUnit $unit, array $tokens, array $rates, ?string $offPeakMultiplier): string
    {
        $cost = $this->baseCost($unit, $tokens, $rates);

        if ($offPeakMultiplier !== null) {
            $cost = Decimal::mul($cost, $offPeakMultiplier);
        }

        return Decimal::roundHalfUp6($cost);
    }

    /** @param array{...} $tokens @param array<string,string> $rates */
    private function baseCost(PriceUnit $unit, array $tokens, array $rates): string
    {
        if ($unit === PriceUnit::Per1mTokensUnified) {
            $total = 0;
            foreach (self::KINDS as $kind) {
                $total += (int) ($tokens[$kind] ?? 0);
            }
            return $this->term($total, $rates['any'] ?? $this->requireRate($rates, 'any'));
        }

        $sum = '0';
        foreach (self::KINDS as $kind) {
            if (!isset($rates[$kind])) {
                throw new InvalidArgumentException("Pricing scheme per_1m_tokens requires the price for \"{$kind}\"");
            }
            $sum = Decimal::add($sum, $this->term((int) ($tokens[$kind] ?? 0), $rates[$kind]));
        }

        return $sum;
    }

    private function term(int $tokens, string $rate): string
    {
        if ($tokens === 0) {
            return '0';
        }
        return Decimal::div(Decimal::mul((string) $tokens, $rate), '1000000');
    }
}
```
