```php
final class SpecReader
{
    public static function object(mixed $value, string $context): array
    {
        if (!is_array($value) || array_is_list($value)) {
            throw new BadInputException("{$context}: expected a JSON object");
        }
        return $value;
    }

    public static function requiredString(array $item, string $key, string $context, int $maxLength = 255): string
    {
        if (!array_key_exists($key, $item)) {
            throw new BadInputException("{$context}: required field {$key} missing");
        }
        $value = $item[$key];
        if (!is_string($value) || $value === '' || mb_strlen($value) > $maxLength) {
            throw new BadInputException("{$context}.{$key}: expected a non-empty string (no more than {$maxLength} characters)");
        }
        return $value;
    }

    public static function nonNegativeInt(array $item, string $key, string $context): int
    {
        if (!array_key_exists($key, $item)) {
            throw new BadInputException("{$context}: required field {$key} missing");
        }
        $value = $item[$key];
        if (!is_int($value) || $value < 0 || $value > PHP_INT_MAX) {
            throw new BadInputException("{$context}.{$key}: expected a non-negative integer");
        }
        return $value;
    }

    /** @return array<string, string> */
    public static function rates(array $item, PriceUnit $unit, string $context): array
    {
        if (!array_key_exists('rates', $item)) {
            throw new BadInputException("{$context}: required field rates missing");
        }
        $rates = $item['rates'];
        if (!is_array($rates) || array_is_list($rates)) {
            throw new BadInputException("{$context}.rates: expected kind → price object");
        }
        $kinds = $unit === PriceUnit::Per1mTokensUnified ? ['any'] : PricingCalculator::KINDS;
        $result = [];
        foreach ($kinds as $kind) {
            if (!array_key_exists($kind, $rates)) {
                throw new BadInputException("{$context}.rates: price for {$kind} missing (required by scheme {$unit->value})");
            }
            $value = $rates[$kind];
            if (is_int($value)) {
                $value = (string) $value;
            } elseif (is_float($value)) {
                if (!is_finite($value) || $value < 0) {
                    throw new BadInputException("{$context}.rates.{$kind}: expected a non-negative price (decimal string)");
                }
                $value = (string) $value;
            } elseif (!is_string($value)) {
                throw new BadInputException("{$context}.rates.{$kind}: expected a price as a decimal string or number");
            }
            DecimalLiteral::assertNonNegative($value, "{$context}.rates.{$kind}");
            $result[$kind] = $value;
        }
        return $result;
    }
}
```

Note: `is_float` → (string) cast: PHP uses serialize_precision (default -1 → shortest round-trip) — "0.3"? 0.3 → "0.3" ✓. 1.25 → "1.25" ✓. OK.

