/**
 * Канонический формат стоимости: ровно 6 знаков после десятичной точки
 * ("14.262499", "1.000000", "0.000000", и т.п.).
 *
 * Если у значения уже больше 6 знаков, сначала выполняется единственное
 * законное округление HALF_UP; иначе хвост дополняется нулями.
 */
public static function money6(string $value): string
{
    $v = self::normalize($value);
    $dot = strrpos($v, '.');
    if ($dot === false) {
        return $v.'000000';
    }

    $frac = substr($v, $dot + 1);
    if (strlen($frac) > self::MONEY_SCALE) {
        return self::roundHalfUp6($v);
    }

    if (strlen($frac) === self::MONEY_SCALE) {
        return $v;
    }

    return $v.str_repeat('0', self::MONEY_SCALE - strlen($frac));
}

private static function normalize(string $value): string
{
    $v = trim($value);
    if ($v === '' || $v === '+' || $v === '-' || $v === '.') {
        throw new InvalidArgumentException("Invalid decimal literal: «{$value}»");
    }

    if ($v !== '0' && $v[0] === '0') {
        // убираем ведущие нули (0.000001, 007 → 7)
        $v = ltrim($v, '0');
        if ($v === '' || $v[0] !== '.') {
            // «007» → «7» ; «0.5» → «.5 → 0.5»
            $v = $v === '' ? '0' : $v;
        }
    }

    if (str_starts_with($v, '.')) {
        $v = '0'.$v;
    }

    return $v;
}

